import pprint
from ta_messaging.message_types_utils import message_exists_in_protocol,\
    message_exists, get_3gpp_name, _map_user_protocol_to_database_protocols
from ta_messaging.exceptions import TranslationOfMessageTypeToAsnNotPossible
from ta_messaging.message_containers import does_message_contain_parsable_containers, get_containers_for_msg
from ta_messaging.logger import configure_csv_logger
from ute_common_abstract_core.message import KeyFindingDict
import logging

container_logger = None


class UnparsedMessage(object):
    '''
    Preparsed domain message that has ability to fully parse itself.

    Object contains all needed protocol data and reference to corresponding parser to create fully functional
    Message object in the future.
    To save time during message source stream analysis,
    full parsing is skipped and has to be invoked explicitly when needed.
    '''
    def __init__(self, owner, msg_payload, message_type, parser, meta_data_dict):
        self.owner = owner
        self.msg_payload = msg_payload
        self.protocol = None
        self.message_type = message_type
        self.parser = parser
        self.meta_data = meta_data_dict
        self._extract_protocol_from_meta()
        self._parsed_message = None
        self.logger_msgs = logging.getLogger('messaging.flows.logic')
        self.logger = self.logger_msgs  # self.logger used by UT (to be refactored)

    def _get_container_logger(self):
        global container_logger
        if container_logger is None:
            _logger = configure_csv_logger('containers')
            container_logger = _logger
            _logger.debug(";".join(['message_name', 'container_key']))
        return container_logger

    def _extract_protocol_from_meta(self):
        if hasattr(self.meta_data, '_fields'):
            # meta id namedtuple
            if 'protocol' in self.meta_data._fields and self.meta_data.protocol is not None:
                self.protocol = _map_user_protocol_to_database_protocols(self.meta_data.protocol)
        else:
            # meta is dict
            if 'protocol' in list(self.meta_data.keys()) and self.meta_data['protocol'] is not None:
                self.protocol = _map_user_protocol_to_database_protocols(self.meta_data['protocol'])

    @classmethod
    def ap_from_hexvalue_and_msg_type(cls, protocol, owner, message_type, data_record, parser):
        '''
            Constructor for message sources catching messages that hold message type in form of ASN.1 value field
            like: RRCConnectionRequest
            So far hex values is supported only for RRC-family protocols

            Message type is not converted to ASN value, just checking if message type has allowed value.
            :param owner: whom the message belongs to (network element identification)
            :param data_record: data_record returned by ta_tshark_hex_parser generator of unprased messages
            :param parser: parser than can fully parse msg_payload
            :return: (UnparsedMessage instance, error msg, debug msg)
            '''
        error_msg = ''
        debug_msg = ''
        protocol = _map_user_protocol_to_database_protocols(protocol)
        if not message_exists_in_protocol(message_type, protocol):
            # log error but allow to proceed!
            err = TranslationOfMessageTypeToAsnNotPossible('Message {} could not be recognized'
                                                           .format(pprint.pformat(data_record.type)))
            error_msg = str(err)
        hex = data_record.hex
        data_record = data_record._asdict()
        data_record['protocol'] = protocol
        data_record['type'] = message_type
        unparsed_msg_instance = cls(owner, hex, message_type, parser, data_record)
        return unparsed_msg_instance, error_msg, debug_msg

    @classmethod
    def from_hexvalue_and_msg_type(cls, owner, data_record, parser):
        '''
            Constructor for message sources catching messages that hold message type in form of ASN.1 value field
            like: RRCConnectionRequest
            So far hex values is supported only for RRC-family protocols

            Message type is not converted to ASN value, just checking if message type has allowed value.
            :param owner: whom the message belongs to (network element identification)
            :param data_record: data_record returned by ta_tshark_hex_parser generator of unprased messages
            :param parser: parser than can fully parse msg_payload
            :return: (UnparsedMessage instance, error msg, debug msg)
            '''
        error_msg = ''
        debug_msg = ''
        if 'protocol' in data_record._fields:
            protocol = data_record.protocol
        else:
            protocol = 'rrc'  # for legacy, hex sources are serving only rrc types
        protocol = _map_user_protocol_to_database_protocols(protocol)
        if not message_exists_in_protocol(data_record.type, protocol):
            # log error but allow to proceed!
            err = TranslationOfMessageTypeToAsnNotPossible('Message {} could not be recognized'
                                                           .format(pprint.pformat(data_record.type)))
            error_msg = str(err)

        unparsed_msg_instance = cls(owner, data_record.hex, data_record.type, parser, data_record)
        return unparsed_msg_instance, error_msg, debug_msg

    @classmethod
    def from_asn1value_msg_type(cls, owner, msg_payload, message_type_value_str, parser, meta_data_dict):
        '''
        Constructor for message sources catching messages that hold message type in form of ASN.1 value field
        like: rrcConnectionRequest
        Such ASN.1 value must be converted to ASN.1 type names: rrcConnectionRequest --> RRCConnectionRequest

        :param owner: whom the message belongs to (network element identification)
        :param msg_payload: raw/unparsed payload to be stored
        :param message_type_value_str: type in ASN.1 value, like rrcConnectionRequest
        :param parser: parser than can fully parse msg_payload
        :param meta_data_dict: dict of available meta data
        :return: (UnparsedMessage instance, error msg, debug msg)
        '''
        error_msg = ''
        debug_msg = ''
        message_type_asnvalue_str = UnparsedMessage._align_message_type_to_asn(message_type_value_str)
        if not message_exists(message_type_asnvalue_str, exists_in='non-3gpp'):
            # log error but allow to proceed!
            err = TranslationOfMessageTypeToAsnNotPossible('Message {} could not be translated to ASN.1 message type'
                                                           .format(pprint.pformat(message_type_value_str)))
            error_msg = str(err)
            message_type = message_type_value_str
        else:
            message_type = get_3gpp_name(message_type_asnvalue_str)
            debug_msg = "{}: {} '{}' {}: '{}'".format(cls.__name__,
                                                      "converting message_type from ASN.1 value name",
                                                      message_type_asnvalue_str,
                                                      "to ASN.1 type name",
                                                      message_type)
        unparsed_msg_instance = cls(owner, msg_payload, message_type, parser, meta_data_dict)
        return unparsed_msg_instance, error_msg, debug_msg

    @classmethod
    def from_msg_type(cls, owner, msg_payload, message_type_value_str, parser, meta_data_dict):
        '''
        Constructor for message sources catching messages that hold message type in form of ASN.1 value field
        like: rrcConnectionRequest
        Message type is not converted to ASN value, just checking if message type has allowed value.

        :param owner: whom the message belongs to (network element identification)
        :param msg_payload: raw/unparsed payload to be stored
        :param message_type_value_str: type in ASN.1 value, like rrcConnectionRequest
        :param parser: parser than can fully parse msg_payload
        :param meta_data_dict: dict of available meta data
        :return: (UnparsedMessage instance, error msg, debug msg)
        '''
        error_msg = ''
        debug_msg = ''
        if not message_exists(message_type_value_str, exists_in='non-3gpp'):
            # log error but allow to proceed!
            err = TranslationOfMessageTypeToAsnNotPossible('Message {} could not be recognized'
                                                           .format(pprint.pformat(message_type_value_str)))
            error_msg = str(err)
        else:
            debug_msg = "{}: {} '{}' {}".format(cls.__name__,
                                                "Message",
                                                message_type_value_str,
                                                "recognized")
        unparsed_msg_instance = cls(owner, msg_payload, message_type_value_str, parser, meta_data_dict)
        return unparsed_msg_instance, error_msg, debug_msg

    @staticmethod
    def _align_message_type_to_asn(message_type):
        return message_type.replace('_', '-')

    def parse(self):
        '''
        Perform full parsing of itself
        :return: Message object
        '''
        if self._parsed_message is None:
            parsed_message_without_containers = self.parser.parse(self)
            parsed_message = self._parse_included_containers(message_type=self.message_type, message_structure=parsed_message_without_containers)
            self._parsed_message = parsed_message
        return self._parsed_message

    def _parse_included_containers(self, message_type, message_structure):
        if UnparsedMessage._if_message_contains_parsable_containers(message_type=message_type):
            containers_for_msg = get_containers_for_msg(message_type, message_structure)
            for container_parse_function in containers_for_msg:
                (field_index, field_key, parsed_container) = container_parse_function(message_structure)
                if parsed_container is not None:
                    message_structure = self._put_parsed_container_into_message_under_key_and_index(new_container=parsed_container,
                                                                                                    original_message=message_structure,
                                                                                                    field_index=field_index,
                                                                                                    field_key=field_key)
                    self._get_container_logger().debug(";".join([message_type, field_key]))
                else:
                    self.logger_msgs.debug('{} Could not parse container: {} from message: {}, possibly container does not exist'
                                           .format(self, field_key, message_type))
        return message_structure

    @staticmethod
    def _if_message_contains_parsable_containers(message_type):
        return does_message_contain_parsable_containers(message_type)

    def _put_parsed_container_into_message_under_key_and_index(self, new_container, original_message, field_index, field_key):
        new_message = original_message
        paths_to_key = KeyFindingDict._find_paths2key(new_message, field_key)
        if field_index in list(range(len(paths_to_key))):
            exec('new_message{}=new_container'.format(paths_to_key[field_index]))
        else:
            self.logger_msgs.debug('{} Index: {} does not exist in paths to key list : {}'.format(self, field_index, paths_to_key))
        return new_message

    def __str__(self):
        output = "UnparsedMsg(%s, owner:%s)" % (self.message_type, self.owner)
        return output


def is_unparsed_message(instance):
    """
    Verifies if given instance is unparsed message
    :param instance:
    :return:
    """
    return isinstance(instance, UnparsedMessage)
